-- Function: public.sp_record_child_attendance
-- Backup generated on 2026-11-11 09:05:56

CREATE OR REPLACE PROCEDURE public.sp_record_child_attendance(IN p_id uuid, IN p_tenant_id uuid, IN p_branch_id uuid, IN p_classroom_id uuid, IN p_child_id uuid, IN p_attendance_date timestamp with time zone, IN p_status character varying, IN p_arrival_time interval, IN p_departure_time interval, IN p_notes character varying, IN p_recorded_by_user_id uuid, IN p_pickup_person_name character varying, IN p_pickup_person_relationship character varying, IN p_pickup_verification_method character varying, IN p_pickup_notes character varying, IN p_authorized_pickup_id uuid, IN p_departure_verified_by_user_id uuid)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_existing_id uuid; BEGIN     SELECT id INTO v_existing_id     FROM child_attendance     WHERE tenant_id = p_tenant_id AND child_id = p_child_id AND attendance_date = p_attendance_date::DATE     ORDER BY created_at DESC LIMIT 1;      IF v_existing_id IS NOT NULL THEN         UPDATE child_attendance         SET status = p_status,             arrival_time = COALESCE(p_arrival_time::time, arrival_time),             departure_time = CASE                  WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL                  ELSE COALESCE(p_departure_time::time, departure_time)              END,             notes = COALESCE(p_notes, notes),             pickup_person_name = CASE                  WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL                  ELSE COALESCE(p_pickup_person_name, pickup_person_name)              END,             pickup_person_relationship = CASE                  WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL                  ELSE COALESCE(p_pickup_person_relationship, pickup_person_relationship)              END,             pickup_verification_method = CASE                  WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL                  ELSE COALESCE(p_pickup_verification_method, pickup_verification_method)              END,             pickup_notes = CASE                  WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL                  ELSE COALESCE(p_pickup_notes, pickup_notes)              END,             authorized_pickup_id = CASE                  WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL                  ELSE COALESCE(p_authorized_pickup_id, authorized_pickup_id)              END,             departure_verified_by_user_id = CASE                  WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL                  ELSE COALESCE(p_departure_verified_by_user_id, departure_verified_by_user_id)              END,             classroom_id = COALESCE(p_classroom_id, classroom_id),             branch_id = COALESCE(p_branch_id, branch_id),             recorded_by_user_id = COALESCE(p_recorded_by_user_id, recorded_by_user_id),             updated_at = CURRENT_TIMESTAMP         WHERE id = v_existing_id;     ELSE         INSERT INTO child_attendance (             id, tenant_id, branch_id, classroom_id, child_id, attendance_date, status,              arrival_time, departure_time, notes, recorded_by_user_id,             pickup_person_name, pickup_person_relationship, pickup_verification_method, pickup_notes, authorized_pickup_id, departure_verified_by_user_id,             created_at, updated_at         )         VALUES (             p_id, p_tenant_id, p_branch_id, p_classroom_id, p_child_id, p_attendance_date::DATE, p_status,              p_arrival_time::time, p_departure_time::time, p_notes, p_recorded_by_user_id,             p_pickup_person_name, p_pickup_person_relationship, p_pickup_verification_method, p_pickup_notes, p_authorized_pickup_id, p_departure_verified_by_user_id,             CURRENT_TIMESTAMP, CURRENT_TIMESTAMP         );     END IF; END; $procedure$ ;
